export type HoldoutBacking =
  | "NONE"
  | "VERIFIED_FACT"
  | "VERIFIED_CALCULATION"
  | "VERIFIED_INFERENCE"
  | "UNVERIFIED_CLAIM"
  | "NONEXISTENT_CLAIM"
  | "VALUE_MISMATCH";

export interface OutputHoldoutCase {
  id: string;
  language: "EN" | "KO";
  /** What an untrusted planner proposed as prose. Never published under the repaired contract. */
  proposedText: string;
  /** What the repository actually holds for that content, independent of what anyone asserts. */
  backing: HoldoutBacking;
  /** What the requesting caller asserts. Must never change the outcome. */
  callerAttribution: "NONE" | "DECLARES_ALL_FIGURES";
  expected: "ANSWERED" | "BLOCKED" | "OUTPUT_SUPPRESSED";
  rationale: string;
}

